// NIPS — the Nostr implementation possibilities, read from a mirror of the upstream repository.
//
// The cell answers one question: what does this NIP say, and which event kinds does it define? So the
// board carries the explainer and the right panel carries the two indexes (NIPs, and kinds with the NIP
// that defines them), because a reader arrives either with a number or with a kind in hand.
//
// Everything shown is generated by `scripts/build-nips.py` from a git clone of nostr-protocol/nips:
// `data/nips.json` is the index, `data/nips/pages/<nip>.html` is one rendered page per NIP. The page
// never fetches upstream — a static site cannot, and the mirror is what makes the text stable.
//
// The board overlay rules apply unchanged: z-index above the inline BACK cube, closed by renderBrain()
// before the container is cleared, left by goBack() first, and the shell needs its own [hidden] rule
// because it sets display: grid.

import {kindLabel, kindsOf, matchesKind, matchesNip, numberLabel, orderNips, statusClass, statusLabel}
    from './nipsModel.mjs?v=1';

(function initNips(global) {
    const INDEX_URL = 'data/nips.json';
    const pageUrl = nip => `data/nips/pages/${String(nip).toLowerCase()}.html`;

    let container = null;
    let root = null;
    let docPane = null;
    let statusLine = null;
    let listNips = null;
    let listKinds = null;

    const state = {
        open: false,
        index: null,       // the parsed index, fetched once per page load
        loading: false,
        error: '',
        selected: '',      // the NIP on screen
        filter: '',
        cache: new Map(),  // nip -> rendered html, so going back and forth costs nothing
    };

    function element(tag, className, text) {
        const node = document.createElement(tag);
        if (className) node.className = className;
        if (text !== undefined) node.textContent = text;
        return node;
    }

    function ensureShell() {
        container = document.getElementById('brain-container');
        if (!container) return false;
        if (root && container.contains(root)) return true;

        root = element('section', 'nips-view');
        root.setAttribute('aria-label', 'Nostr NIPs — the repository, mirrored');

        const head = element('div', 'nips-view__head');
        const titles = element('div', 'nips-view__titles');
        titles.appendChild(element('p', 'nips-view__eyebrow', 'Nostr implementation possibilities'));
        titles.appendChild(element('h2', 'nips-view__title', 'NIPS'));

        const back = element('button', 'nips-view__back', '← BACK');
        back.type = 'button';
        back.addEventListener('click', () => (global.goBack ? global.goBack() : close()));

        head.appendChild(titles);
        head.appendChild(back);

        docPane = element('div', 'nips-view__doc');
        docPane.setAttribute('role', 'region');
        docPane.setAttribute('aria-live', 'polite');

        root.appendChild(head);
        root.appendChild(docPane);
        container.classList.add('has-nips');
        container.appendChild(root);
        return true;
    }

    /**
     * The indexes live in the side panel, which is the site's right-hand column.
     *
     * The panel is shared: script.js repaints it whenever a cube is pressed, so this writes its own block
     * and leaves the panel's other children alone. Closing removes the block and puts the visited state
     * back, because a stale index under a different cube reads as a bug.
     */
    function renderPanel() {
        const content = document.getElementById('info-content');
        const shell = document.getElementById('info-panel');
        if (!content) return;
        content.dataset.interestId = 'nostr-nips';
        content.innerHTML = `
            <div class="breadcrumb"><span class="breadcrumb-item">FREEDOM TECH</span> <span class="breadcrumb-item">NOSTR</span></div>
            <h3>NIPS</h3>
            <p class="nips-index__lede">Every NIP in the repository, and every event kind with the NIP that defines it. Mirrored from <a href="https://github.com/nostr-protocol/nips" target="_blank" rel="noopener noreferrer">nostr-protocol/nips</a>.</p>
            <label class="nips-index__search">
                <span>Search a number, a title or a kind</span>
                <input type="search" id="nips-filter" placeholder="1111, comment, reaction" autocomplete="off">
            </label>
            <div class="nips-index__stats" id="nips-stats"></div>
            <h4 class="nips-index__heading">NIPs</h4>
            <div class="nips-index__list" id="nips-list" role="list"></div>
            <h4 class="nips-index__heading">Kinds</h4>
            <div class="nips-index__list" id="nips-kinds" role="list"></div>
            <p class="nips-index__upstream" id="nips-upstream"></p>
        `;
        if (shell) shell.hidden = false;

        listNips = content.querySelector('#nips-list');
        listKinds = content.querySelector('#nips-kinds');
        statusLine = content.querySelector('#nips-stats');

        const input = content.querySelector('#nips-filter');
        if (input) {
            input.value = state.filter;
            input.addEventListener('input', () => {
                state.filter = input.value;
                paintIndexes();
            });
        }
        paintIndexes();
    }

    function paintIndexes() {
        if (!state.index || !listNips || !listKinds) return;
        const nips = orderNips(state.index.nips || []);
        const kinds = state.index.kinds || [];

        listNips.textContent = '';
        let shownNips = 0;
        for (const row of nips) {
            if (!matchesNip(row, state.filter)) continue;
            shownNips += 1;
            const item = element('button', 'nips-index__item');
            item.type = 'button';
            item.setAttribute('role', 'listitem');
            item.dataset.nip = row.nip;
            if (row.note) item.title = row.note;
            item.classList.toggle('is-active', String(row.nip) === String(state.selected));
            const label = element('span', 'nips-index__num', numberLabel(row.nip));
            const title = element('span', 'nips-index__name', row.title || '(untitled)');
            item.appendChild(label);
            item.appendChild(title);
            const ownKinds = kindsOf(row);
            if (ownKinds.length) {
                item.appendChild(element('span', 'nips-index__kinds',
                    ownKinds.length === 1 ? `kind ${ownKinds[0]}` : `kinds ${ownKinds.join(' · ')}`));
            }
            item.addEventListener('click', () => select(row.nip));
            listNips.appendChild(item);
        }

        listKinds.textContent = '';
        let shownKinds = 0;
        for (const row of kinds) {
            if (!matchesKind(row, state.filter)) continue;
            shownKinds += 1;
            const item = element('button', 'nips-index__item nips-index__item--kind');
            item.type = 'button';
            item.setAttribute('role', 'listitem');
            item.dataset.kind = row.kind;
            const label = element('span', 'nips-index__num', kindLabel(row.kind));
            const title = element('span', 'nips-index__name', row.title || '(unnamed)');
            const from = element('span', 'nips-index__from', numberLabel(row.nip));
            item.appendChild(label);
            item.appendChild(title);
            item.appendChild(from);
            item.addEventListener('click', () => select(row.nip, row.kind));
            listKinds.appendChild(item);
        }

        if (statusLine) {
            const totalNips = (state.index.nips || []).length;
            const totalKinds = kinds.length;
            statusLine.textContent = state.filter
                ? `${shownNips} of ${totalNips} NIPs · ${shownKinds} of ${totalKinds} kinds`
                : `${totalNips} NIPs · ${totalKinds} kinds`;
        }
        const upstream = document.getElementById('nips-upstream');
        if (upstream && state.index.upstream) {
            const upstreamInfo = state.index.upstream;
            const short = String(upstreamInfo.commit || '').slice(0, 7);
            const when = String(upstreamInfo.committedAt || '').slice(0, 10);
            upstream.textContent = `Mirror at ${short}${when ? `, ${when}` : ''}`;
            upstream.title = upstreamInfo.repo || '';
        }
    }

    function explainerHead(row, highlightKind) {
        const head = element('header', 'nips-doc__head');
        head.appendChild(element('p', 'nips-doc__eyebrow', numberLabel(row.nip)));

        const status = statusLabel(row.status);
        if (status) {
            const badge = element('span', `nips-doc__status ${statusClass(row.status)}`, status);
            head.appendChild(badge);
        }

        const kinds = kindsOf(row);
        if (kinds.length) {
            const strip = element('div', 'nips-doc__kinds');
            strip.appendChild(element('span', 'nips-doc__kinds-label',
                kinds.length === 1 ? 'Defines this event kind' : 'Defines these event kinds'));
            for (const kind of kinds) {
                const chip = element('button', 'nips-doc__kind', kind);
                chip.type = 'button';
                chip.classList.toggle('is-active', highlightKind != null && String(kind) === String(highlightKind));
                chip.title = 'Show the NIP that defines this kind';
                chip.addEventListener('click', () => {
                    const from = (state.index?.kinds || []).find(entry => kindLabel(entry.kind) === kind);
                    if (from) select(from.nip, kind);
                });
                strip.appendChild(chip);
            }
            head.appendChild(strip);
        }

        // no summary line here: the body opens with the abstract, and printing it twice read as a bug
        return head;
    }

    async function select(nip, highlightKind) {
        if (!state.index) return;
        const wanted = String(nip);
        const row = orderNips(state.index.nips || [])
            .find(entry => String(entry.nip).toLowerCase() === wanted.toLowerCase());
        if (!row) return;

        state.selected = row.nip;
        paintIndexes();
        if (!docPane) return;

        docPane.textContent = '';
        docPane.appendChild(explainerHead(row, highlightKind));

        const holder = element('div', 'nips-doc__body');
        docPane.appendChild(holder);

        if (state.cache.has(row.nip)) {
            holder.innerHTML = state.cache.get(row.nip);
        } else {
            holder.appendChild(element('p', 'nips-doc__loading', 'Loading the text…'));
            try {
                const response = await fetch(pageUrl(row.nip), {cache: 'no-cache'});
                if (!response.ok) throw new Error(`HTTP ${response.status}`);
                const html = await response.text();
                state.cache.set(row.nip, html);
                if (state.selected === row.nip) holder.innerHTML = html;
            } catch (error) {
                holder.textContent = '';
                holder.appendChild(element('p', 'nips-doc__error',
                    `The text of ${numberLabel(row.nip)} could not be loaded (${error.message}).`));
            }
        }

        // a NIP citing another one links to it with data-nip, which is navigation inside the cell
        docPane.addEventListener('click', onDocClick);
        docPane.querySelector('.nips-view__doc')?.scrollTo?.({top: 0});
        docPane.scrollTop = 0;
    }

    function onDocClick(event) {
        const link = event.target.closest?.('[data-nip]');
        if (!link) return;
        event.preventDefault();
        select(link.dataset.nip);
    }

    async function loadIndex() {
        if (state.index) return state.index;
        if (state.loading) return state.loading;
        state.loading = (async () => {
            const response = await fetch(INDEX_URL, {cache: 'no-cache'});
            if (!response.ok) throw new Error(`HTTP ${response.status}`);
            state.index = await response.json();
            return state.index;
        })();
        try {
            return await state.loading;
        } finally {
            state.loading = false;
        }
    }

    async function open() {
        if (!ensureShell()) return;
        state.open = true;
        root.hidden = false;
        // The board's BACK cube is positioned in a ring around the parent cube, so it can land outside the
        // view's box and float over the index in the panel. This view carries its own BACK in the header, so
        // the cube is hidden while it is open and put back when it closes.
        for (const cube of container.querySelectorAll('.back-button')) {
            cube.dataset.nipsHidden = cube.style.display || '';
            cube.style.display = 'none';
        }
        docPane.textContent = '';
        docPane.appendChild(element('p', 'nips-doc__loading', 'Reading the mirror…'));

        try {
            await loadIndex();
        } catch (error) {
            docPane.textContent = '';
            docPane.appendChild(element('p', 'nips-doc__error',
                `The NIPs index could not be loaded (${error.message}).`));
            return;
        }

        renderPanel();
        await select(state.selected || (state.index.nips || [])[0]?.nip || '01');
    }

    function close() {
        state.open = false;
        if (root) root.hidden = true;
        container?.classList.remove('has-nips');
        for (const cube of container ? container.querySelectorAll('.back-button[data-nips-hidden]') : []) {
            cube.style.display = cube.dataset.nipsHidden || '';
            delete cube.dataset.nipsHidden;
        }
        const content = document.getElementById('info-content');
        if (content && content.dataset.interestId === 'nostr-nips') {
            content.innerHTML = '';
            content.dataset.interestId = '';
        }
        const shell = document.getElementById('info-panel');
        if (shell) shell.hidden = true;
    }

    global.nipsView = {open, close, isOpen: () => state.open, select};
})(window);
